//! Number options parsed the way the Python originals parse them.
//!
//! crapper's and dryer's `--threshold` are CPython `float()`. Both ports call
//! [`python_float`], so one implementation answers for both tools and the
//! table generated by `scripts/dry_threshold_oracle.py` from both pinned
//! originals checks it.

use crate::digits::DECIMAL_DIGIT_RUNS;

/// The ASCII value of a decimal digit from any script (Unicode category Nd),
/// as CPython `int()` and `float()` read it.
pub fn decimal_digit(char: char) -> Option<u32> {
    let code = char as u32;
    DECIMAL_DIGIT_RUNS
        .iter()
        .find_map(|(start, end)| (code >= *start && code <= *end).then(|| code - start))
}

/// CPython `float()` of a string: `None` where Python raises `ValueError`.
///
/// Python trims Unicode White_Space, reads every Nd digit as its ASCII digit,
/// allows `_` only between two digits, and then takes a decimal literal or a
/// signed `inf`/`infinity`/`nan` in any case. Any other non-ASCII character is
/// refused.
pub fn python_float(raw: &str) -> Option<f64> {
    let mut text = String::new();
    for char in raw.trim().chars() {
        match decimal_digit(char) {
            Some(digit) => text.push(char::from_digit(digit, 10).unwrap()),
            None if char.is_ascii() => text.push(char),
            None => return None,
        }
    }
    let bytes = text.as_bytes();
    for (index, byte) in bytes.iter().enumerate() {
        if *byte == b'_' {
            let digit = |at: Option<&u8>| at.is_some_and(u8::is_ascii_digit);
            if index == 0 || !digit(bytes.get(index - 1)) || !digit(bytes.get(index + 1)) {
                return None;
            }
        }
    }
    let text = text.replace('_', "");
    let lower = text.to_ascii_lowercase();
    // Python's own grammar allows at most one sign.
    let (sign, unsigned) = match lower.as_bytes().first() {
        Some(b'-') => (-1.0, &lower[1..]),
        Some(b'+') => (1.0, &lower[1..]),
        _ => (1.0, lower.as_str()),
    };
    if ["inf", "infinity", "nan"].contains(&unsigned) {
        return lower.parse().ok().or_else(|| {
            if unsigned == "nan" {
                Some(f64::NAN)
            } else {
                Some(sign * f64::INFINITY)
            }
        });
    }
    if !unsigned.starts_with(|c: char| c.is_ascii_digit() || c == '.') {
        return None;
    }
    text.parse().ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn decode(encoded: &str) -> String {
        let mut text = String::new();
        let mut chars = encoded.chars();
        while let Some(char) = chars.next() {
            if char != '\\' {
                text.push(char);
                continue;
            }
            match chars.next().unwrap() {
                '\\' => text.push('\\'),
                'u' => {
                    assert_eq!(Some('{'), chars.next());
                    let hex: String = chars.by_ref().take_while(|c| *c != '}').collect();
                    text.push(char::from_u32(u32::from_str_radix(&hex, 16).unwrap()).unwrap());
                }
                other => panic!("unknown escape \\{other}"),
            }
        }
        text
    }

    /// Expected values are the pinned originals' `float()` reprs.
    #[test]
    fn every_pinned_float_spelling_converts_to_the_same_value() {
        let mut rows = 0;
        for line in include_str!("../../../fixtures/dry/threshold/cases.tsv")
            .lines()
            .filter(|line| !line.starts_with('#'))
        {
            let fields: Vec<&str> = line.split('\t').collect();
            let ["threshold", value, expected] = fields[..] else {
                panic!("unexpected case line {line:?}");
            };
            let value = decode(value);
            let actual = python_float(&value);
            match expected.strip_prefix("ok:") {
                Some("nan") => assert!(actual.is_some_and(f64::is_nan), "{value:?}"),
                Some(repr) => {
                    let expected: f64 = repr.parse().unwrap();
                    let actual = actual.unwrap_or_else(|| panic!("{value:?} refused"));
                    assert_eq!(expected.to_bits(), actual.to_bits(), "{value:?}");
                }
                None => assert_eq!(None, actual, "{value:?}"),
            }
            rows += 1;
        }
        assert_eq!(rows, 104);
    }

    #[test]
    fn the_generated_digit_runs_are_ten_wide_and_ordered() {
        let mut previous = None;
        for (start, end) in DECIMAL_DIGIT_RUNS {
            assert_eq!(9, end - start, "run {start:04X}-{end:04X}");
            assert!(previous.is_none_or(|last| last < *start));
            for digit in 0..10 {
                let char = char::from_u32(start + digit).unwrap();
                assert_eq!(Some(digit), decimal_digit(char), "U+{:04X}", start + digit);
            }
            previous = Some(*end);
        }
    }
}
